import { getSignedUrl } from "@aws-sdk/cloudfront-signer";

/** Object keys are generated by the app (uuid + extension) or come from the seed list. */
export const VIDEO_KEY_PATTERN = /^[a-z0-9][a-z0-9-]{0,80}\.(mp4|webm)$/;

export interface SignVideoUrlInput {
  /** CloudFront domain in AWS (https://dxxxx.cloudfront.net) or the local edge (http://localhost:4001). */
  baseUrl: string;
  /** Object key under the /videos/ prefix, e.g. "welcome.webm". */
  key: string;
  keyPairId: string;
  privateKey: string;
  ttlSeconds: number;
  algorithm?: "SHA1" | "SHA256";
  /** Current time in milliseconds (injectable for tests). */
  now?: number;
}

export interface SignedVideoUrl {
  url: string;
  /** Unix time in seconds after which CloudFront (or the local edge) answers 403. */
  expiresAt: number;
}

/**
 * Builds a CloudFront signed URL (canned policy) for one private video.
 * The same function runs locally and in AWS; only baseUrl and the key pair change.
 */
export function signVideoUrl(input: SignVideoUrlInput): SignedVideoUrl {
  if (!VIDEO_KEY_PATTERN.test(input.key)) {
    throw new Error(`Refusing to sign unexpected video key: ${JSON.stringify(input.key)}`);
  }
  if (!Number.isInteger(input.ttlSeconds) || input.ttlSeconds < 1 || input.ttlSeconds > 86_400) {
    throw new Error("ttlSeconds must be an integer between 1 and 86400");
  }
  const nowMs = input.now ?? Date.now();
  const expiresAt = Math.floor(nowMs / 1000) + input.ttlSeconds;
  const url = getSignedUrl({
    url: `${input.baseUrl.replace(/\/+$/, "")}/videos/${input.key}`,
    keyPairId: input.keyPairId,
    privateKey: input.privateKey,
    // The SDK rounds to whole seconds; pass an exact second so expiresAt matches.
    dateLessThan: new Date(expiresAt * 1000),
    algorithm: input.algorithm ?? "SHA1",
  });
  return { url, expiresAt };
}
